	private static Map<Map<String, Value>, Long> evaluate(Repository repository, String query,
			Map<String, Value> parameters) {
		try (var connection = repository.getConnection()) {
			var prepared = connection.prepareTupleQuery(PREFIX + query);
			parameters.forEach(prepared::setBinding);
			Map<Map<String, Value>, Long> bag = new HashMap<>();
			try (var rows = prepared.evaluate()) {
				while (rows.hasNext()) {
					Map<String, Value> row = new HashMap<>();
					rows.next().forEach(binding -> row.put(binding.getName(), binding.getValue()));
					bag.merge(Map.copyOf(row), 1L, Long::sum);
				}
			}
			return bag;
		}
	}

